|   |           `-- finally -> remove abort listener, unsubscribe, dispose, remove session
|   `-- Check cancellation again -> [D] submitStoredDiagramEdit
|       `-- Domain validates submitted edit and issues immutable revision
|           `-- Revision issuance precedes canvas installation
|-- Install through supplied canvas port
|   |-- Edit -> canvas.apply(runId, expectedVersion, baseRevisionId, revision, variants)
|   |   `-- Controller checks document version and base revision at mutation boundary
|   |-- Create/extend -> read latest snapshot -> canvas.create(runId, latestVersion, diagrams)
|   |   |-- Place at explicit origin or beside anchor
|   |   |-- Extension revalidates source anchors
|   |   `-- VERSION_CONFLICT -> reread/retry placement, at most 3 attempts
|   |       `-- Reuse generated diagrams
|   `-- Acknowledged receipt -> completed
|       `-- Record document version/results and expose captured next agent context
|-- DiagramBatchService: stage operations before one canvas application
|   |-- Validate batch and deduplicate by sessionId + requestId + signature
|   |-- Capture one shared snapshot with requested revisions
|   |   |-- Require expected version
|   |   `-- Reject multiple edit targets referring to the same logical diagram
|   |-- Run child DiagramEditService operations sequentially
|   |   |-- Each child reads the shared snapshot, not previous staged outputs
|   |   |-- Extra retained revisions require the same document version
|   |   |-- Child apply/create ports append to staged edits/creations
|   |   `-- Failure or cancellation before final application -> no canvas.batch call
|   `-- All children complete -> canvas.batch(runId, expectedVersion, edits, creations)
|       |-- One application of staged operations
|       `-- Receipt updates batch and child result versions -> completed
`-- Run outcomes and cancellation
    |-- Cancellation while generating -> abort active generation; status=cancelled
    |   `-- Batch cancellation also cancels its active child
    |-- Application dispatched -> cancellation no longer labels outcome cancelled
    |-- Applying + CANVAS_TIMEOUT / CANVAS_UNAVAILABLE / PERSISTENCE_PENDING
    |   `-- awaiting-acknowledgement -> same-request retry reuses prepared application
    |-- VERSION_CONFLICT -> conflict
    `-- Other errors -> failed; batch errors identify operation index when available"}{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "properties": {
    "explanation": {
      "type": "string",
      "minLength": 1,
      "maxLength": 6000
