228:       const ref = index + 1;
229:       let revision: DiagramRevision | undefined = history?.diagramRevisions[reference.revisionId];
230:       if (!revision) try { revision = getDiagramRevision(reference.revisionId); } catch { /* reported below */ }
231:       if (!revision || revision.diagramId !== reference.diagramId) throw Error(`PROMPT_REFERENCE_NOT_FOUND: [ref ${ref}] ${reference.label} is not available`);
232:       const common = { ref, label: reference.label, diagramId: reference.diagramId, revisionId: reference.revisionId };
233:       if (reference.kind === 'diagram') return { ...common, kind: 'diagram', ascii: revision.diagram.content.ascii };
234:       const lines = revision.diagram.content.ascii.split('\n'), range = reference.range;
235:       if (range.endLine > lines.length) throw Error(`PROMPT_REFERENCE_INVALID: [ref ${ref}] range is outside its revision`);
