237:       const unknown = reference.nodeIds.find(id => !known.has(id));
238:       if (unknown) throw Error(`PROMPT_REFERENCE_INVALID: [ref ${ref}] node ${unknown} is not in its revision`);
239:       return { ...common, kind: 'nodes', range,
240:         excerpt: reference.nodeIds.length && reference.nodeIds.every(id => diagramContentNodes(revision.diagram.content).some(node => node.id === id))
