290: function findParent(box: GridBox, id: string): Extract<GridBox, { kind: 'container' }> | undefined {
291:   if (box.kind !== 'container') return undefined;
292:   return box.children.some(child => child.id === id) ? box : box.children.map(child => findParent(child, id)).find(Boolean);
