9: export function createValidatedSubmission<T>(options: ValidatedSubmissionOptions<T>) {
10:   let accepted: T | undefined;
11: 
12:   return {
13:     promptGuideline: `Call ${options.toolName} with the final candidate. If it is rejected, correct the reported issues and call it again.`,
14: 
15:     get value(): T | undefined {
16:       return accepted;
17:     },
18: 
19:     async execute(_toolCallId: string, candidate: T) {
20:       const validationError = await options.validate(candidate);
21:       if (validationError) {
22:         const correction = options.correctionPrompt
23:           ? `${options.correctionPrompt} Then call ${options.toolName} again.`
24:           : `Correct the submission and call ${options.toolName} again.`;
25:         return {
26:           content: [{
27:             type: "text" as const,
28:             text: `Submission rejected: ${validationError}. ${correction}`
29:           }],
30:           details: { accepted: false },
31:           terminate: false
32:         };
33:       }
34: 
35:       accepted = candidate;
36:       return {
37:         content: [{ type: "text" as const, text: options.acceptedMessage(candidate) }],
38:         details: {
39:           accepted: true,
40:           ...options.acceptedDetails?.(candidate)
41:         },
42:         terminate: true
43:       };
44:     }
45:   };
